"""YAML renderer. Standard library only -- see CONTRIBUTING.md."""

import math
import re

from plugins import PluginError, Renderer, register

# Strings matching this may be emitted unquoted: start with an alphanumeric or
# underscore, then only alphanumerics, underscore, dash, dot, slash, space.
_PLAIN_SAFE = re.compile(r"^[A-Za-z0-9_][A-Za-z0-9_\-./ ]*$")

# Words YAML would otherwise read as booleans/nulls.
_RESERVED = {"true", "false", "null", "yes", "no", "on", "off", "~"}


def _double_quote(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ord(ch) < 0x20 or ch == "\x7f":
            out.append(f"\\x{ord(ch):02x}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def _looks_numeric(s: str) -> bool:
    try:
        float(s)
    except ValueError:
        return False
    return True


def _format_str(s: str) -> str:
    if s.lower() in _RESERVED or _looks_numeric(s):
        return _double_quote(s)
    if _PLAIN_SAFE.match(s):
        return s
    return _double_quote(s)


def _format_scalar(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return ".nan"
        if math.isinf(value):
            return ".inf" if value > 0 else "-.inf"
        return repr(value)
    if isinstance(value, str):
        return _format_str(value)
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for i, row in enumerate(rows):
            if not row:
                lines.append("- {}" if i == 0 else "  {}")
                continue
            for k, v in row.items():
                if not isinstance(k, str):
                    raise PluginError("yaml keys must be strings")
                prefix = "- " if i == 0 else "  "
                lines.append(f"{prefix}{_format_str(k)}: {_format_scalar(v)}")
        return "\n".join(lines) + "\n"

